package fixture;import java.util.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.InteractionHand;import net.minecraft.network.chat.Component;import net.minecraft.world.effect.MobEffectInstance;
public class Game{
 public static class Tag{public Map<String,Object>d=new HashMap<>();public boolean getBoolean(String s){return Boolean.TRUE.equals(d.get(s));}public String getString(String s){return String.valueOf(d.getOrDefault(s,""));}public int getInt(String s){return ((Number)d.getOrDefault(s,0)).intValue();}public long getLong(String s){return ((Number)d.getOrDefault(s,0L)).longValue();}public void putBoolean(String s,boolean b){d.put(s,b);}public void putString(String s,String b){d.put(s,b);}public void putInt(String s,int b){d.put(s,b);}public void putLong(String s,long b){d.put(s,b);}public void remove(String s){d.remove(s);}}
 public static class World{public Random random=new Random(4);public long time;public boolean client;public boolean isClientSide(){return client;}public long getGameTime(){return time;}public void playSound(Object p,Object pos,Object sound,Object type,float a,float b){}}
 public static class Part{public float currentHealth;public int getMaxHealth(){return 10;}}
 public static class Model implements Iterable<Part>{public boolean criticalConditionActive=true;public int unconsciousTicks=2000,defibCalls,bareCalls,sync;public List<Part>parts=new ArrayList<>();public Model(){for(int i=0;i<8;i++)parts.add(new Part());}public Iterator<Part>iterator(){return parts.iterator();}public boolean isUnconscious(){return unconsciousTicks>0;}public int getUnconsciousTicks(){return unconsciousTicks;}public boolean defibrillatorRescueFromCriticalState(Object p,boolean delay){defibCalls++;return false;}public boolean rescueFromCriticalState(Object p,Object h,boolean delay){bareCalls++;return false;}public void clearUnconsciousState(){unconsciousTicks=0;}public void clearUnconsciousPenalties(Object p){}public void syncVanillaHealth(Object p){sync++;}public void scheduleResync(){}}
 public static class Actor extends net.minecraft.world.entity.player.Player{public World world=new World();public Tag tag=new Tag();public EnumMap<EquipmentSlot,ItemStack>gear=new EnumMap<>(EquipmentSlot.class);public List<Object>bag=new ArrayList<>();public Model model=new Model();public Map<Object,MobEffectInstance>effects=new HashMap<>();public UUID uuid=UUID.randomUUID();public boolean alive=true,using;public ItemStack use=ItemStack.EMPTY;public List<String>messages=new ArrayList<>();public Actor(){for(EquipmentSlot slot:EquipmentSlot.values())gear.put(slot,ItemStack.EMPTY);}public World level(){return world;}public Tag getPersistentData(){return tag;}public ItemStack getItemBySlot(EquipmentSlot s){return gear.get(s);}public void setItemSlot(EquipmentSlot s,Object item){gear.put(s,(ItemStack)item);}public ItemStack getMainHandItem(){return gear.get(EquipmentSlot.MAINHAND);}public ItemStack getOffhandItem(){return gear.get(EquipmentSlot.OFFHAND);}public ItemStack getItemInHand(InteractionHand h){return h==InteractionHand.MAIN_HAND?getMainHandItem():getOffhandItem();}public List<ItemStack>getArmorSlots(){return List.of(gear.get(EquipmentSlot.HEAD),gear.get(EquipmentSlot.CHEST),gear.get(EquipmentSlot.LEGS),gear.get(EquipmentSlot.FEET));}public boolean isAlive(){return alive;}public boolean isRemoved(){return false;}public double distanceToSqr(Object o){return 0;}public void displayClientMessage(Component c,boolean a){messages.add(c.text());}public UUID getUUID(){return uuid;}public void addEffect(MobEffectInstance e){effects.put(e.effect,e);}public boolean removeEffect(Object e){return effects.remove(e)!=null;}public MobEffectInstance getEffect(Object e){return effects.get(e);}public float getMaxHealth(){return 20;}public void setForcedPose(Object p){}public void setShiftKeyDown(boolean s){}public void refreshDimensions(){}public boolean isUsingItem(){return using;}public ItemStack getUseItem(){return use;}public Object blockPosition(){return new Object();}public void swing(Object h){}public Component getDisplayName(){return Component.literal("Tester");}public int getId(){return 1;}}
 public record Event(Actor getEntity,ItemStack getItem,int getDuration){} public static class Key{public boolean down;public boolean isDown(){return down;}}public static class Options{public Key keyUse=new Key();}public static class Client{public Actor player;public Object screen;public Options options=new Options();}
}
